 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support contact form - Support</title>
   <style>
     :root {
       --color-bg: #0b1120;
       --color-panel: #111827;
       --color-panel-strong: #1f2937;
       --color-text: #f9fafb;
       --color-muted-text: #cbd5e1;
       --color-border: #475569;
       --color-focus: #38bdf8;
       --color-danger: #fda4af;
       --color-success: #86efac;
       --color-accent: #60a5fa;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Arial, Helvetica, sans-serif;
       background:
         radial-gradient(circle at top, #1e293b 0, #0b1120 45%),
         var(--color-bg);
       color: var(--color-text);
       line-height: 1.5;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       transform: translateY(-220%);
       padding: 0.75rem 1rem;
       border-radius: 0.75rem;
       background: var(--color-text);
       color: #020617;
       font-weight: 700;
       text-decoration: none;
       z-index: 10;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     main {
       display: grid;
       place-items: center;
       min-height: 100vh;
       padding: 2rem 1rem;
     }

     .card {
       width: min(100%, 42rem);
       padding: 2rem;
       border: 1px solid var(--color-border);
       border-radius: 1.5rem;
       background: linear-gradient(180deg, rgba(31, 41, 55, 0.96), rgba(15, 23, 42, 0.96));
       box-shadow: 0 1.5rem 4rem rgba(2, 6, 23, 0.45);
     }

     h1 {
       margin: 0 0 0.75rem;
       font-size: clamp(2rem, 4vw, 2.75rem);
       line-height: 1.1;
     }

     .intro,
     .required-note {
       margin: 0 0 1.25rem;
       color: var(--color-muted-text);
     }

     .required-indicator {
       color: var(--color-danger);
       font-weight: 700;
     }

     form {
       display: grid;
       gap: 1rem;
     }

     .form-field {
       display: grid;
       gap: 0.45rem;
     }

     label {
       font-weight: 700;
     }

     input {
       width: 100%;
       padding: 0.9rem 1rem;
       border: 1px solid var(--color-border);
       border-radius: 0.9rem;
       background: var(--color-panel);
       color: var(--color-text);
       font: inherit;
       transition: border-color 120ms ease, box-shadow 120ms ease, background-color 120ms ease;
     }

     input::placeholder {
       color: #94a3b8;
     }

     input:hover {
       border-color: #64748b;
     }

     input:focus-visible,
     button:focus-visible {
       outline: 2px solid transparent;
       box-shadow: 0 0 0 0.2rem var(--color-bg), 0 0 0 0.38rem var(--color-focus);
     }

     input[aria-invalid="true"] {
       border-color: var(--color-danger);
       background: var(--color-panel-strong);
     }

     .field-help {
       color: var(--color-muted-text);
       font-size: 0.95rem;
     }

     .field-error {
       min-height: 1.25rem;
       color: var(--color-danger);
       font-size: 0.95rem;
       font-weight: 700;
     }

     .actions {
       margin-top: 0.5rem;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.35rem;
       background: linear-gradient(135deg, var(--color-accent), #8b5cf6);
       color: var(--color-text);
       font: inherit;
       font-weight: 700;
       cursor: pointer;
     }

     button:hover {
       filter: brightness(1.08);
     }

     .status-message {
       min-height: 1.5rem;
       margin: 0.5rem 0 0;
       color: var(--color-success);
       font-weight: 700;
     }

     @media (max-width: 40rem) {
       .card {
         padding: 1.5rem;
       }
     }

     @media (forced-colors: active) {
       body {
         background: Canvas;
         color: CanvasText;
       }

       .card,
       input,
       button {
         background: Canvas;
         color: CanvasText;
         border: 1px solid ButtonBorder;
         box-shadow: none;
       }

       .skip-link {
         background: Highlight;
         color: HighlightText;
       }

       input:focus-visible,
       button:focus-visible {
         outline: 2px solid Highlight;
         box-shadow: none;
       }

       .field-error {
         color: CanvasText;
       }

       .status-message {
         color: CanvasText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>
   <main id="maincontent" tabindex="-1">
     <section class="card" aria-labelledby="support-heading">
       <h1 id="support-heading">Contact support</h1>
       <p class="intro">Tell us how to reach you and a support specialist will follow up as soon as possible.</p>
       <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-describedby="full-name-error"
             aria-errormessage="full-name-error"
           >
           <p id="full-name-error" class="field-error"></p>
         </div>

         <div class="form-field">
           <label for="email">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
           <input
             id="email"
             name="email"
             type="email"
             inputmode="email"
             autocomplete="email"
             required
             aria-describedby="email-error"
             aria-errormessage="email-error"
           >
           <p id="email-error" class="field-error"></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number</label>
           <input
             id="phone"
             name="phone"
             type="tel"
             inputmode="tel"
             autocomplete="tel"
             aria-describedby="phone-help phone-error"
             aria-errormessage="phone-error"
           >
           <p id="phone-help" class="field-help">Optional. Use numbers only or include separators, for example: 555-123-4567 or +1 555 123 4567.</p>
           <p id="phone-error" class="field-error"></p>
         </div>

         <div class="actions">
           <button type="submit">Send request</button>
         </div>

         <p id="form-status" class="status-message" role="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const statusMessage = document.getElementById('form-status');

     const fields = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Error: Enter your full name.';
           }
           return '';
         }
       },
       {
         input: document.getElementById('email'),
         error: document.getElementById('email-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Error: Enter your email address.';
           }
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return 'Error: Enter a valid email address like name@example.com.';
           }
           return '';
         }
       },
       {
         input: document.getElementById('phone'),
         error: document.getElementById('phone-error'),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return '';
           }
           const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
           if (!phonePattern.test(trimmedValue)) {
             return 'Error: Enter a valid phone number using digits, spaces, parentheses, or hyphens.';
           }
           return '';
         }
       }
     ];

     function setFieldState(field, message) {
       field.error.textContent = message;
       field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       setFieldState(field, message);
       return !message;
     }

     fields.forEach((field) => {
       field.input.addEventListener('blur', () => {
         validateField(field);
       });

       field.input.addEventListener('input', () => {
         if (field.error.textContent) {
           validateField(field);
         }
         statusMessage.textContent = '';
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       statusMessage.textContent = '';

       const invalidFields = fields.filter((field) => !validateField(field));

       if (invalidFields.length > 0) {
         invalidFields[0].input.focus();
         return;
       }

       statusMessage.textContent = 'All fields look good. This demo form is ready for server integration.';
     });
   </script>
 </body>
 </html>

